  font-family: 'ServiceNow Sans';
  font-weight: 400;
  font-style: normal;
  font-display: swap;
  src: url('https://www.servicenow.com/etc.clientlibs/ds/clientlibs/clientlib-arc-commons/resources/fonts/ServiceNowSans-Regular.woff2') format('woff2');
}

:root {
  color-scheme: dark;
  --mono: ui-monospace, SFMono-Regular, Consolas, monospace;
  --sans: 'ServiceNow Sans', Arial, Helvetica, sans-serif;
}

#app[data-theme='dark'], #app:not([data-theme]) {
  --bg: #080b0e;
  --bg-rgb: 8, 11, 14;
  --ink: #dce6e9;
  --dim: #829199;
  --cyan: #9beae4;
  --caption: #a1afb5;
  --reference: #8a9aa3;
  --reference-dim: #61747e;
  --text-shadow: #080b0e99;
}

#app[data-theme='light'] {
  --bg: #ededea;
  --bg-rgb: 237, 236, 234;
  --ink: #23292c;
  --dim: #6a7378;
  --cyan: #1f8f77;
  --caption: #4d565a;
  --reference: #5c6569;
  --reference-dim: #838c90;
  --text-shadow: #ffffffb3;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100svh;
  display: grid;
  place-items: center;
  background: #050709;
  color: var(--ink);
  font-family: var(--sans);
  transition: color .25s ease;
}

/* Same idea as square.css's #app rule (aspect-ratio box + cqw-scaled
   children), but 16:9 instead of 1:1, and sized by percentage instead of
   viewport units — width:100% of the parent (browser tab or host iframe
   box) has no ambiguity between standalone and embedded contexts the way
   vw/svh can. Keeps data-layout="square" on the canvas (see wide.html) —
   that composition's camera math is fully proportional (fractions of
   width/height), not the widescreen path's fixed-pixel margins, so it
   holds at any aspect ratio and any embed size without cropping. */
#app {
  position: relative;
  width: 100%;
  max-width: 1920px;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  isolation: isolate;
  container-type: inline-size;
  background: var(--bg);
  transition: background .25s ease;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

#scene:active { cursor: grabbing; }

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(var(--bg-rgb), 0.94) 0%, rgba(var(--bg-rgb), 0.72) 24%, rgba(var(--bg-rgb), 0.3) 44%, rgba(var(--bg-rgb), 0) 66%),
    linear-gradient(180deg, rgba(var(--bg-rgb), 0.33) 0%, rgba(var(--bg-rgb), 0) 36%, rgba(var(--bg-rgb), 0) 86%, rgba(var(--bg-rgb), 0.47) 100%);
  transition: background .25s ease;
}

.intro {
  position: absolute;
  z-index: 2;
  top: 9cqw;
  left: 6cqw;
  width: 46cqw;
  pointer-events: none;
  color: var(--ink);
  text-shadow: 0 2px 14px var(--text-shadow);
  transition: color .25s ease, text-shadow .25s ease;
}

.eyebrow {
  font: 1.04cqw var(--mono);
  letter-spacing: 0.2cqw;
  color: var(--cyan);
}

h1 {
  margin: 2.2cqw 0 1.45cqw;
  font-size: 5.55cqw;
  font-weight: 800;
  line-height: 1.04;
  letter-spacing: -0.19cqw;
}

p {
  margin: 0;
  max-width: 36cqw;
  font-size: 1.5cqw;
  line-height: 1.65;
  letter-spacing: 0.015cqw;
  color: var(--caption);
}

.reference {
  margin-top: 3.1cqw;
  font: 0.84cqw / 1.9 var(--mono);
  letter-spacing: 0.11cqw;
  color: var(--reference);
}

.reference span {
  display: block;
  color: var(--reference-dim);
}

#theme-toggle {
  position: absolute;
  z-index: 3;
  top: 4.5cqw;
  right: 4.5cqw;
  padding: 0.7cqw 1.3cqw;
  font: 0.85cqw var(--mono);
  letter-spacing: 0.15cqw;
  color: var(--ink);
  background: rgba(var(--bg-rgb), 0.55);
  border: 1px solid var(--dim);
  border-radius: 999px;
  cursor: pointer;
  transition: color .25s ease, background .25s ease, border-color .25s ease;
}

#theme-toggle:hover { color: var(--cyan); border-color: var(--cyan); }

[hidden] { display: none !important; }
