      const shoulder = bodyPoint(pose, [side * shoulderWidth, 6.13, 0]);
      const hand = bodyPoint(pose, pose.hands[index]);
      const elbowPole = bodyDirection(pose, [side * 0.65, -0.2, -0.9]);
