        line([[s * 27.8, 5, z], [s * 27.8, 27, z]], '#66838b', 0.9, 0.35);
      }
    }
    for (const s of [-1, 1]) {
      box([s * 24, 18, -32], [1.9, 36, 2.5], 'bay');
      box([s * 24, 18, -30.6], [0.16, 27, 0.03], 'brace');
    }
    box([0, 37, -32], [49, 2.2, 2.5], 'bay');
  }

  function unknownUnit(t) {
