      ctx.fillText('U N K N O W N', center.x, center.y + 110);
      ctx.font = '8px ui-monospace, monospace';ctx.fillStyle = '#81968d';
      ctx.fillText('SIGNATURE NOT RECOGNIZED', center.x, center.y + 134);
